import * as React from 'react'
import { createPortal } from 'react-dom'
import { Dialog, DialogContent, DialogTitle, DialogDescription } from '@/components/ui/dialog'
import { Popover, PopoverAnchor, PopoverContent } from '@/components/ui/popover'
import { Button } from '@/components/ui/button'
export interface TourStep {
  title: string
  description: string
  target?: string
  placement?: 'top' | 'right' | 'bottom' | 'left'
  beforeEnter?: (signal: AbortSignal) => void | Promise<void>
}
export function Tour({
  steps,
  open,
  onOpenChange,
  onFinish,
}: {
  steps: TourStep[]
  open: boolean
  onOpenChange: (open: boolean) => void
  onFinish?: () => void
}) {
  const [current, setCurrent] = React.useState(0),
    [target, setTarget] = React.useState<HTMLElement | null>(null),
    [bounds, setBounds] = React.useState<DOMRect | null>(null)
  const returnFocus = React.useRef<HTMLElement | null>(null)
  const titleId = React.useId(),
    descriptionId = React.useId()
  React.useEffect(() => {
    if (open) {
      setCurrent(0)
      returnFocus.current = document.activeElement as HTMLElement
    } else returnFocus.current?.focus()
  }, [open])
  const step = steps[current]
  const [preparing, setPreparing] = React.useState(false),
    [error, setError] = React.useState('')
  const enter = React.useRef(step?.beforeEnter)
  enter.current = step?.beforeEnter
  React.useEffect(() => {
    if (!open || !enter.current) return
    const controller = new AbortController()
    setPreparing(true)
    setError('')
    Promise.resolve(enter.current(controller.signal))
      .catch((error) => {
        if (!controller.signal.aborted) setError(String(error))
      })
      .finally(() => {
        if (!controller.signal.aborted) setPreparing(false)
      })
    return () => controller.abort()
  }, [open, current])
  React.useEffect(() => {
    if (!open || !step?.target || preparing) {
      setTarget(null)
      setBounds(null)
      return
    }
    let element: HTMLElement | null = null
    try {
      element = document.querySelector<HTMLElement>(step.target)
    } catch {
      return
    }
    setTarget(element)
    if (!element) return
    element.scrollIntoView({ behavior: 'smooth', block: 'center' })
    const update = () => setBounds(element!.getBoundingClientRect())
    update()
    window.addEventListener('scroll', update, true)
    window.addEventListener('resize', update)
    const observer = new ResizeObserver(update)
    observer.observe(element)
    return () => {
      window.removeEventListener('scroll', update, true)
      window.removeEventListener('resize', update)
      observer.disconnect()
    }
  }, [open, current, step?.target, preparing])
  if (!step) return null
  const controls = (
    <div className="mt-5 flex items-center justify-between gap-3">
      {error && (
        <p role="alert" className="text-xs text-destructive">
          {error}
        </p>
      )}
      <Button size="sm" variant="ghost" onClick={() => onOpenChange(false)}>
        Skip tour
      </Button>
      <div className="flex gap-2">
        <Button
          size="sm"
          variant="outline"
          disabled={preparing || current === 0}
          onClick={() => setCurrent((c) => c - 1)}
        >
          Back
        </Button>
        <Button
          size="sm"
          disabled={preparing}
          onClick={() => {
            if (current === steps.length - 1) {
              onOpenChange(false)
              onFinish?.()
            } else setCurrent((c) => c + 1)
          }}
        >
          {current === steps.length - 1 ? 'Finish' : 'Next'}
        </Button>
      </div>
    </div>
  )
  if (target && open)
    return (
      <>
        <Popover open={open} onOpenChange={onOpenChange} modal>
          <PopoverAnchor virtualRef={{ current: target }} />
          <PopoverContent
            side={step.placement ?? 'bottom'}
            sideOffset={14}
            className="z-[70] w-80 max-w-[calc(100vw-24px)] p-5"
            role="dialog"
            aria-labelledby={titleId}
            aria-describedby={descriptionId}
            onCloseAutoFocus={(e) => {
              e.preventDefault()
              if (!open) returnFocus.current?.focus()
            }}
          >
            <span className="text-xs font-medium text-primary">
              A quick introduction · {current + 1} of {steps.length}
            </span>
            <h3 id={titleId} className="mt-3 font-semibold">
              {step.title}
            </h3>
            <p id={descriptionId} className="mt-2 text-sm leading-relaxed text-muted-foreground">
              {step.description}
            </p>
            {controls}
          </PopoverContent>
        </Popover>
        {bounds &&
          createPortal(
            <div
              aria-hidden
              className="pointer-events-none fixed z-[60] rounded-lg border-2 border-primary transition-[top,left,width,height] duration-200 motion-reduce:transition-none"
              style={{
                top: bounds.top - 5,
                left: bounds.left - 5,
                width: bounds.width + 10,
                height: bounds.height + 10,
                boxShadow: '0 0 0 9999px rgb(0 0 0 / .25)',
              }}
            />,
            document.body,
          )}
      </>
    )
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <span className="text-xs font-medium text-primary">
          A quick introduction · {current + 1} of {steps.length}
        </span>
        <DialogTitle>{step.title}</DialogTitle>
        <DialogDescription>{step.description}</DialogDescription>
        {controls}
      </DialogContent>
    </Dialog>
  )
}

import { usePortalContainer } from '@/components/ui/config-provider'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { XIcon } from 'lucide-react'
import { Dialog as DialogPrimitive } from 'radix-ui'

import { Button } from '@/components/ui/button'

function Dialog({ ...props }: React.ComponentProps<typeof DialogPrimitive.Root>) {
  return <DialogPrimitive.Root data-slot="dialog" {...props} />
}

function DialogTrigger({ ...props }: React.ComponentProps<typeof DialogPrimitive.Trigger>) {
  return <DialogPrimitive.Trigger data-slot="dialog-trigger" {...props} />
}

function DialogPortal({ ...props }: React.ComponentProps<typeof DialogPrimitive.Portal>) {
  return (
    <DialogPrimitive.Portal container={usePortalContainer()} data-slot="dialog-portal" {...props} />
  )
}

function DialogClose({ ...props }: React.ComponentProps<typeof DialogPrimitive.Close>) {
  return <DialogPrimitive.Close data-slot="dialog-close" {...props} />
}

function DialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Overlay>) {
  return (
    <DialogPrimitive.Overlay
      data-slot="dialog-overlay"
      className={cn(
        'fixed inset-0 z-50 bg-black/50 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:animate-in data-[state=open]:fade-in-0',
        className,
      )}
      {...props}
    />
  )
}

function DialogContent({
  className,
  children,
  showCloseButton = true,
  draggable,
  resizable,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Content> & {
  showCloseButton?: boolean
  draggable?: boolean
  resizable?: boolean
}) {
  const [position, setPosition] = React.useState({ x: 0, y: 0 }),
    drag = React.useRef<{
      x: number
      y: number
      px: number
      py: number
      limitX: number
      limitY: number
    } | null>(null)
  return (
    <DialogPortal data-slot="dialog-portal">
      <DialogOverlay />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        className={cn(
          'fixed top-[50%] left-[50%] z-50 grid w-full max-w-[calc(100%-2rem)] translate-x-[-50%] translate-y-[-50%] gap-4 rounded-lg border bg-background p-6 shadow-lg duration-200 outline-none data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 sm:max-w-lg',
          className,
        )}
        {...props}
        style={{
          ...(draggable
            ? {
                transform: `translate(calc(-50% + ${position.x}px),calc(-50% + ${position.y}px))`,
                translate: 'none',
              }
            : {}),
          ...(resizable
            ? {
                resize: 'both',
                width: 'min(512px,calc(100vw - 32px))',
                overflow: 'auto',
                minWidth: 260,
                minHeight: 150,
                maxWidth: 'calc(100vw - 32px)',
                maxHeight: 'calc(100vh - 32px)',
              }
            : {}),
          ...props.style,
        }}
        onPointerDown={(event) => {
          props.onPointerDown?.(event)
          if (
            !draggable ||
            (event.target as HTMLElement).closest('button,input,textarea,select,a') ||
            !(event.target as HTMLElement).closest(
              '[data-slot="dialog-header"],[data-slot="dialog-title"]',
            )
          )
            return
          const bounds = event.currentTarget.getBoundingClientRect()
          drag.current = {
            x: event.clientX,
            y: event.clientY,
            px: position.x,
            py: position.y,
            limitX: Math.max(0, (innerWidth - bounds.width) / 2 - 16),
            limitY: Math.max(0, (innerHeight - bounds.height) / 2 - 16),
          }
          event.currentTarget.setPointerCapture(event.pointerId)
        }}
        onPointerMove={(event) => {
          props.onPointerMove?.(event)
          if (drag.current)
            setPosition({
              x: Math.max(
                -drag.current.limitX,
                Math.min(drag.current.limitX, drag.current.px + event.clientX - drag.current.x),
              ),
              y: Math.max(
                -drag.current.limitY,
                Math.min(drag.current.limitY, drag.current.py + event.clientY - drag.current.y),
              ),
            })
        }}
        onPointerUp={(event) => {
          drag.current = null
          props.onPointerUp?.(event)
        }}
        onLostPointerCapture={() => {
          drag.current = null
        }}
      >
        {children}
        {showCloseButton && (
          <DialogPrimitive.Close
            data-slot="dialog-close"
            className="absolute top-4 right-4 rounded-xs opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:outline-hidden disabled:pointer-events-none data-[state=open]:bg-accent data-[state=open]:text-muted-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4"
          >
            <XIcon />
            <span className="sr-only">Close</span>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </DialogPortal>
  )
}

function DialogHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="dialog-header"
      className={cn('flex flex-col gap-2 text-center sm:text-left', className)}
      {...props}
    />
  )
}

function DialogFooter({
  className,
  showCloseButton = false,
  children,
  ...props
}: React.ComponentProps<'div'> & {
  showCloseButton?: boolean
}) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn('flex flex-col-reverse gap-2 sm:flex-row sm:justify-end', className)}
      {...props}
    >
      {children}
      {showCloseButton && (
        <DialogPrimitive.Close asChild>
          <Button variant="outline">Close</Button>
        </DialogPrimitive.Close>
      )}
    </div>
  )
}

function DialogTitle({ className, ...props }: React.ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn('text-lg leading-none font-semibold', className)}
      {...props}
    />
  )
}

function DialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn('text-sm text-muted-foreground', className)}
      {...props}
    />
  )
}

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
}

import { contrastForeground } from '@/lib/contrast'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { Direction } from 'radix-ui'
export interface UIConfig {
  density: 'comfortable' | 'compact'
  direction: 'ltr' | 'rtl'
  locale: string
}
const ConfigContext = React.createContext<UIConfig>({
  density: 'comfortable',
  direction: 'ltr',
  locale: 'en-US',
})
const PortalContext = React.createContext<HTMLElement | null>(null)
export const usePortalContainer = () => React.useContext(PortalContext) ?? undefined
export const useUIConfig = () => React.useContext(ConfigContext)
export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
  density?: UIConfig['density']
  direction?: UIConfig['direction']
  locale?: string
  accent?: string
  radius?: number
}
export function ConfigProvider({
  density: providedDensity,
  direction: providedDirection,
  locale: providedLocale,
  accent,
  radius,
  children,
  style,
  className,
  ...props
}: ConfigProviderProps) {
  const parent = useUIConfig(),
    density = providedDensity ?? parent.density,
    direction = providedDirection ?? parent.direction,
    locale = providedLocale ?? parent.locale
  const [portal, setPortal] = React.useState<HTMLDivElement | null>(null)
  return (
    <ConfigContext.Provider value={{ density, direction, locale }}>
      <PortalContext.Provider value={portal}>
        <Direction.Provider dir={direction}>
          <div
            dir={direction}
            lang={locale}
            data-density={density}
            className={cn('ergon-root', className)}
            style={
              {
                ...(accent
                  ? {
                      '--primary': accent,
                      '--ring': accent,
                      '--primary-foreground': contrastForeground(accent),
                    }
                  : {}),
                ...(radius !== undefined ? { '--radius': `${radius}px` } : {}),
                ...style,
              } as React.CSSProperties
            }
            {...props}
          >
            {children}
            <div ref={setPortal} data-ergon-portals="" style={{ display: 'contents' }} />
          </div>
        </Direction.Provider>
      </PortalContext.Provider>
    </ConfigContext.Provider>
  )
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { Slot } from 'radix-ui'
import { Loader2 } from 'lucide-react'

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        destructive:
          'bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40',
        outline:
          'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        link: 'text-primary underline-offset-4 hover:underline',
        soft: 'bg-primary/10 text-primary hover:bg-primary/15',
        success: 'bg-emerald-600 text-white hover:bg-emerald-700',
        warning: 'bg-amber-400 text-amber-950 hover:bg-amber-500',
        dashed:
          'border border-dashed bg-background text-foreground hover:border-primary hover:text-primary',
      },
      size: {
        default:
          'h-[var(--ergon-control-height,2.25rem)] px-4 py-[var(--ergon-control-py,0.5rem)] has-[>svg]:px-3',
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-xs': "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

/**
 * Composes button variants, loading state, and optional slot rendering. Compact-density styles travel with the installed source.
 */
function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size }), className)}
      aria-busy={loading || undefined}
      {...props}
      disabled={props.disabled || loading}
    >
      {asChild ? (
        children
      ) : (
        <>
          {loading && <Loader2 className="animate-spin" />}
          {children}
        </>
      )}
    </Comp>
  )
}

export { Button, buttonVariants }

import { usePortalContainer } from '@/components/ui/config-provider'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { Popover as PopoverPrimitive } from 'radix-ui'

function Popover({ ...props }: React.ComponentProps<typeof PopoverPrimitive.Root>) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />
}

function PopoverTrigger({ ...props }: React.ComponentProps<typeof PopoverPrimitive.Trigger>) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
}

function PopoverContent({
  className,
  align = 'center',
  sideOffset = 4,
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Content>) {
  return (
    <PopoverPrimitive.Portal container={usePortalContainer()}>
      <PopoverPrimitive.Content
        data-slot="popover-content"
        align={align}
        sideOffset={sideOffset}
        className={cn(
          'z-50 w-72 origin-(--radix-popover-content-transform-origin) rounded-md border bg-popover p-4 text-popover-foreground shadow-md outline-hidden data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95',
          className,
        )}
        {...props}
      />
    </PopoverPrimitive.Portal>
  )
}

function PopoverAnchor({ ...props }: React.ComponentProps<typeof PopoverPrimitive.Anchor>) {
  return <PopoverPrimitive.Anchor data-slot="popover-anchor" {...props} />
}

function PopoverHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="popover-header"
      className={cn('flex flex-col gap-1 text-sm', className)}
      {...props}
    />
  )
}

function PopoverTitle({ className, ...props }: React.ComponentProps<'h2'>) {
  return <div data-slot="popover-title" className={cn('font-medium', className)} {...props} />
}

function PopoverDescription({ className, ...props }: React.ComponentProps<'p'>) {
  return (
    <p
      data-slot="popover-description"
      className={cn('text-muted-foreground', className)}
      {...props}
    />
  )
}

export {
  Popover,
  PopoverTrigger,
  PopoverContent,
  PopoverAnchor,
  PopoverHeader,
  PopoverTitle,
  PopoverDescription,
}
